contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: caller supplies an address target and an amount to send
    // We require this contract has enough ETH to forward 'amount'.
    function run(address user, uint256 amount) public {
        require(address(this).balance >= amount);

        // observe old balance
        uint256 oldBal = c.getBalance(user);

        // call addToBalance on behalf of this contract, but we want effect for `user`.
        // To have the recorded sender be `user`, we need to call from `user` — however
        // tests are run from this contract. The contract C uses msg.sender for mapping key,
        // so to target `user` we simply call as this contract and compare its own balance.
        // Therefore we restrict to testing for this contract's address as the caller.
        // Enforce that 'user' equals this contract so msg.sender matches observed balance.
        require(user == address(this));

        // perform the payable call to addToBalance forwarding amount
        c.addToBalance{value: amount}();

        // observe new balance
        uint256 newBal = c.getBalance(user);

        // General invariant: newBal == oldBal + amount
        assert(newBal == oldBal + amount);
    }

    // allow this contract to receive ETH so tests can forward value
    receive() external payable {}
}

