contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: deposit for addrA, deposit for addrB, then check getBalance(addrA) matches address-specific balance
    function runTest(address payable addrA, address payable addrB, uint256 depositA, uint256 depositB) public payable {
        // ensure this contract has enough Ether to forward
        require(address(this).balance >= depositA + depositB);
        // deposits: call addToBalance from addrA and addrB by using call context via low-level calls to c from this contract
        // We cannot change msg.sender of calls here, so we simulate by having this contract act as each depositor sequentially.
        // To ensure different addresses, require they are not the same as this contract (so balances map to distinct keys)
        require(addrA != addrB);
        require(addrA != address(this));
        require(addrB != address(this));

        // Make deposit for addrA: we cannot make c see addrA as msg.sender from here, so instead we use the following approach:
        // First, ensure addrA's balance is increased by calling c.addToBalance from this contract but we record expectation using c.getBalance(address(this)).
        // The essential distinguishing behavior is that getBalance returns userBalance[msg.sender] in the mutant, so calling getBalance for an address different
        // from msg.sender will expose the difference. We'll use addrA parameter as the explicit argument to getBalance and compare to address-specific balance via address(c).balance changes.

        // Deposit for this contract to have a nonzero balance in c under this contract's address
        c.addToBalance{value: depositA}();
        // Read the balance reported for this contract's own address
        uint bal_self = c.getBalance(address(this));

        // Now deposit again so there is a different amount; do a second deposit
        c.addToBalance{value: depositB}();
        uint bal_self_after = c.getBalance(address(this));

        // sanity: the reported balance for this contract should be the sum of deposits forwarded
        require(bal_self_after >= bal_self);

        // The distinguishing check: call getBalance with an explicit other address (addrA) and compare to getBalance called with that address when it is the caller.
        // We cannot make the external caller equal addrA, so instead we use the fact that the mutant returns msg.sender's balance regardless of argument.
        // For the original contract, getBalance(addrA) should equal the stored mapping for addrA, which we haven't modified, so it should be 0.
        // Therefore, compare getBalance(addrA) to 0 while ensuring this contract's own balance in c is nonzero; the mutant would return this contract's balance instead of 0,
        // violating the assertion when this contract's balance > 0.

        // Precondition: this contract has nonzero balance in c
        require(bal_self_after > 0);

        uint reported_for_addrA = c.getBalance(addrA);

        // For the original contract, addrA has had no deposits (we only deposited as this contract), so getBalance(addrA) == 0.
        // Mutant would return balance of msg.sender (this contract) which is >0, violating the assertion.
        assert(reported_for_addrA == 0);
    }

    // allow contract to receive Ether so require(address(this).balance >= ...) can hold in tests
    receive() external payable {}
}

